import random

def initialize_grid(N, k, config_type, config_params=None):
    """Initializes an N x N grid with k infected cells based on config_type."""
    grid = np.zeros((N, N), dtype=int) # 0: Sterile (White), 1: Infected (Black)

    if config_type == "compact":
        # A dense square or near-square cluster
